export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_PERCENT = 10;
const PERCENT = 100;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

function basePremiumOf(item: Item): number {
  return BASE_PREMIUMS[item.type] ?? 0;
}

/**
 * Premiums are accumulated in percent-scaled units so that percentage
 * modifiers stay exact; only the final amount is rounded (up, in the
 * MHPCO's favour).
 */
function quotePremium(items: Item[]): number {
  const base = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const scaled = base * PERCENT + base * FIRST_INSURANCE_PERCENT;

  return Math.ceil(scaled / PERCENT) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): StepResult[] {
  return scenario.steps.map((step) => ({
    premium: quotePremium((step as QuoteStep).items),
  }));
}

