const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;

interface Policy {
  items: Item[];
  remainingCap: number;
}

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => {
    unitBasePremium(item.type);

    return sum + (INSURANCE_VALUES[item.type] ?? 0);
  }, 0);
}

function payoutFor(damage: Damage): number {
  return Math.max(0, damage.amount - DEDUCTIBLE);
}

function settleClaim(policy: Policy, step: ClaimStep): StepResult {
  const desired = step.incident.damages.reduce(
    (sum, damage) => sum + payoutFor(damage),
    0,
  );
  const payout = Math.min(Math.floor(desired), policy.remainingCap);
  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  let quotesSoFar = 0;

  return scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy);

      if (policy === undefined) {
        throw new Error(`step ${String(step.policy)} is not a policy`);
      }

      return settleClaim(policy, step);
    }

    const premium = quotePremium(step.items, scenario.customer, quotesSoFar);
    quotesSoFar += 1;
    policies.set(index, {
      items: step.items,
      remainingCap: insuranceSum(step.items) * CAP_FACTOR,
    });

    return { premium };
  });
}

